result.text:
case "new-sale": {
  openInvoiceModal({
    mode: "new",
    preset: { kind: "LIQUIDACION", direction: "INGRESO" },
  });
  return;
}
case "export-sales-csv": {
  exportSalesCsv();
  return;
}
case "toggle-status": {
  const inv = toggleInvoiceStatus(id);
  if (inv) {
    toast(inv.status === STATUS.PAID ? "Marcada como pagada." : "Marcada como pendiente.");
    render();
  }
  return;
}
case "edit-invoice": {
  const inv = getState().invoices.find((i) => i.id === id);
  if (inv) openInvoiceModal({ mode: "edit", invoice: inv });
  return;
}
case "delete-invoice": {
  const inv = getState().invoices.find((i) => i.id === id);
  if (!inv) return;
  const ok = await confirmDialog({
    title: "Borrar la factura",
